// Sessions of Part III (spring) and Part IV (summer). Same shape as sessions1.js.
const p = (v, d = 0) => (v * 100).toFixed(d) + '%', n = (v) => Math.round(v).toLocaleString('en-US');
const S = (id, core, place, plate, credited, lines, qa, covers, ev, sus, slot, talk, wren, src) => ({ id, part: id.startsWith('IV-') ? 4 : 3, core, place, plate, credited, lines, qa, covers, ev, sus, slot, talk, wren, src });
const worst = (C) => Object.entries(C.groups).sort((a, b) => b[1].drop - a[1].drop).map(([k, g]) => [C.groupNames[k], g.drop]);

export const PART3 = [
  S('III-1', false, 'manchester', ['Alan Turing', '“Computing Machinery and Intelligence”', '1950', 'University of Manchester'], [],
    ['Alan Turing was working at the University of Manchester when he wrote this paper in 1950.', 'Instead of arguing about what “thinking” means, he proposed a game. A judge exchanges typed messages with a person and a machine, and tries to tell which is which.', 'He then answered nine objections to the idea, one by one.'],
    ['He wanted a question about machines that could actually be tested.', 'Passing for a person in a chat is not the same as understanding, and critics have said so ever since.', 'The game still frames arguments about what today’s chat programs can do.'],
    ['What AI is', 'The imitation game and its critics', 'Narrow and general AI'],
    (C) => `In a small blind test at the desk, readers were handed two lists without labels. More of them preferred the staff’s picks to Marginalia’s. Few could say why.`, [[4, -1]], 'evaluate',
    'What question would you ask to tell a person from a machine?', 'If it fools you, does that mean it thinks?', ['Turing, A. M. (1950). Computing Machinery and Intelligence. Mind, 59(236).']),
  S('III-2', false, 'mit', ['Joseph Weizenbaum', 'ELIZA', '1966', 'MIT'], [],
    ['Joseph Weizenbaum wrote ELIZA at MIT in the mid-1960s.', 'It looked for keywords in what you typed and answered from a script of templates. Its best-known script played a therapist who turns your sentences into questions.', 'People confided in it, including people who knew how it worked. That troubled him for the rest of his life.'],
    ['He wanted to show how far simple pattern matching could go in conversation.', 'People credit a program with understanding it does not have.', 'Many help-desk bots are still keywords and templates underneath.'],
    ['Rule-based programs', 'Pattern matching', 'Why people read minds into machines'],
    (C) => `Before Marginalia, the desk kept ${C.planted.deskRules} hand-written rules for suggesting books. They were crude, and anyone could read every one of them.`, [], 'model',
    'Have you ever said “thank you” to a machine? Why?', 'How can something answer without understanding?', ['Weizenbaum, J. (1966). ELIZA: a computer program for the study of natural language communication between man and machine. Communications of the ACM, 9(1).']),
  S('III-3', false, 'ibm', ['Arthur Samuel', 'A checkers player that learns', '1959', 'IBM'], ['Murray Campbell', 'Feng-hsiung Hsu', 'Joseph Hoane'],
    ['Arthur Samuel wrote a checkers program at IBM in the 1950s that improved by playing against itself.', 'It looked a few moves ahead and scored each position with a formula, and it adjusted the formula’s weights from experience.', 'In 1997 another IBM machine, Deep Blue, won a six-game match against the world chess champion using far deeper search.'],
    ['He wanted a program that got better at a task without being told how.', 'A program pursues exactly what its scoring formula counts, and nothing else.', 'Search plus a learned score is still how machines play board games.'],
    ['Game playing', 'Search', 'Evaluation functions', 'Learning by self-play'],
    (C) => `A machine pursues what its evaluation function counts. Marginalia’s counts one thing: whether the next loan was one of its five.`, [[4, -1]], 'model',
    'In a board game you know, what do you look at to tell who is ahead?', 'What if the thing it counts is the wrong thing?', ['Samuel, A. L. (1959). Some Studies in Machine Learning Using the Game of Checkers. IBM Journal of Research and Development, 3(3).']),
  S('III-4', false, 'cmu', ['Dean Pomerleau', 'ALVINN', '1989', 'Carnegie Mellon University'], [],
    ['Dean Pomerleau’s ALVINN was a small neural network that steered a van.', 'It watched a person drive through a low-resolution camera and learned to turn the wheel the same way.', 'A driver who never drifts never shows the network how to recover, so he made shifted copies of each picture with the right correction attached.'],
    ['He wanted a vehicle to learn road-following from examples instead of hand-written rules.', 'Trained only on good driving, it has never seen the situations its own small errors lead to.', 'Learning by imitation, with deliberately added recoveries, is still used for robots and cars.'],
    ['Autonomous driving', 'Levels of automation', 'Learning by imitation'],
    (C) => `A model trained only on its own road has never seen the other one. Marginalia has never seen what readers do with a shelf it did not choose.`, [[5, 1]], 'model',
    'If you only ever watched perfect cycling, would you know what to do in a wobble?', 'Why does it need to see mistakes?', ['Pomerleau, D. A. (1989). ALVINN: An Autonomous Land Vehicle in a Neural Network. Advances in Neural Information Processing Systems 1.']),
  S('III-5', false, 'mit', ['Edmond Awad, Iyad Rahwan and colleagues', 'The Moral Machine experiment', '2018', 'MIT Media Lab'], [],
    ['The Moral Machine was a website from MIT’s Media Lab that asked people to choose between two outcomes for a self-driving car.', 'Millions of people in more than two hundred countries and territories answered.', 'The 2018 paper found broad agreements, and real differences between regions. Deciding whose preferences should count is not a technical question.'],
    ['They wanted to know what people expect from machines that make choices.', 'Any fixed rule gives an answer somewhere that its own author rejects.', 'Product teams and regulators now ask whose priorities a system encodes.'],
    ['Ethics of autonomous systems', 'Rules against outcomes', 'Whose preferences count'],
    (C) => `Whoever sets the objective decides who is served. The Common Shelf’s board set one number, and it was not chosen by the readers.`, [], 'explain',
    'Three people want the last two seats on the bus. Write a rule. Does it ever feel unfair?', 'Who gets to decide the rule?', ['Awad, E., et al. (2018). The Moral Machine experiment. Nature, 563.']),
  S('III-6', true, 'mit', ['Joy Buolamwini', 'Gender Shades', '2018', 'MIT Media Lab'], ['Timnit Gebru'],
    ['Joy Buolamwini, at the MIT Media Lab, tested three commercial systems that guess a person’s gender from a photograph.', 'Each reported high accuracy overall. Broken down by skin type and gender, the error rates were far apart.', 'The method is the lesson: measure each group, not only the average.'],
    ['She wanted to know whether these products worked equally well for everyone.', 'An average can be excellent while one group is badly served.', 'Audits by group are now expected before a system is trusted.'],
    ['Auditing a system across groups', 'Error rates by group', 'Fairness measures and their conflicts'],
    (C) => { const w = worst(C); return `The narrowing was not shared evenly. Variety per loan fell most for ${w[0][0].toLowerCase()} (${p(w[0][1])}), ${w[1][0].toLowerCase()} (${p(w[1][1])}) and ${w[2][0].toLowerCase()} (${p(w[2][1])}). For ${w[w.length - 1][0].toLowerCase()} it fell ${p(w[w.length - 1][1])}.`; }, [[1, -1], [5, 1]], 'evaluate',
    'Is a rule fair if it works for most people? Who is “most”?', 'How would you check whether something is fair to everyone?', ['Buolamwini, J., & Gebru, T. (2018). Gender Shades: Intersectional Accuracy Disparities in Commercial Gender Classification. Proceedings of Machine Learning Research, 81.']),
  S('III-7', true, 'berlin', ['Oskar Pfungst', 'Clever Hans', '1907', 'Berlin'], ['Sebastian Lapuschkin', 'Wojciech Samek', 'Klaus-Robert Müller'],
    ['In Berlin in the early 1900s a horse named Hans seemed to do arithmetic, tapping out answers with his hoof.', 'The psychologist Oskar Pfungst tested him with care and reported in 1907 that Hans was reading tiny, unintended movements of the person asking.', 'In 2019 a Berlin group showed image classifiers doing the same kind of thing: scoring well by reading a mark in the corner of the pictures.'],
    ['He wanted to know what the horse was really responding to.', 'A right answer does not show that the right thing was learned.', 'Checking what a model looks at is part of testing it.'],
    ['Shortcut learning', 'Spurious cues', 'Looking at what a model uses'],
    (C) => `Marginalia 3 leans hardest on one input: how often a title was borrowed last month. Its link to what gets shown is ${C.importance.lastMonth.toFixed(2)}. For the quality of the book it is ${C.importance.quality.toFixed(2)}.`, [[5, 2]], 'explain',
    'How do you know a friend really understood the homework and did not copy?', 'If the horse got it right, why does it matter how?', ['Pfungst, O. (1907). Das Pferd des Herrn von Osten (Der Kluge Hans). Barth.', 'Lapuschkin, S., et al. (2019). Unmasking Clever Hans predictors and assessing what machines really learn. Nature Communications, 10.']),
  S('III-8', false, 'nvidia', ['Alex Krizhevsky and Geoffrey Hinton', 'AlexNet', '2012', 'recorded at the University of Toronto'], ['Ilya Sutskever'],
    ['In 2012 Alex Krizhevsky, Ilya Sutskever and Geoffrey Hinton, at Toronto, entered a yearly contest to label more than a million photographs.', 'Their network was deep, and too big for one graphics card, so they split it across two.', 'It won by a wide margin, and within a couple of years most of the field had changed direction.'],
    ['They wanted to see how far a large network could go given enough pictures and enough arithmetic.', 'More data of the same kind teaches more of the same.', 'Large networks on graphics hardware became the normal way to do machine vision.'],
    ['Deep learning at scale', 'ReLU', 'Dropout', 'Augmentation', 'Graphics processors'],
    (C) => `More data did not help the rare books. Loans stayed near ${n(C.y.loans[5])} a month, and by year six ${p(C.y.top100[5])} of them were the same hundred titles.`, [[5, 1]], 'model',
    'If you read the same book a hundred times, do you know a hundred books?', 'Is more always better?', ['Krizhevsky, A., Sutskever, I., & Hinton, G. E. (2012). ImageNet Classification with Deep Convolutional Neural Networks. Advances in Neural Information Processing Systems 25.']),
  S('III-9', false, 'microsoft', ['Kaiming He, Xiangyu Zhang and Shaoqing Ren', 'Residual networks', '2015', 'recorded at Microsoft Research Asia, Beijing'], ['Jian Sun'],
    ['A deeper network should do at least as well as a shallow one. In practice, past a certain depth, results got worse even on the training data.', 'Kaiming He, Xiangyu Zhang, Shaoqing Ren and Jian Sun let each block add a correction to its input instead of replacing it.', 'With those shortcut connections they trained networks more than a hundred layers deep.'],
    ['They wanted depth to stop hurting.', 'Without a short path the training signal fades before it reaches the early layers.', 'Shortcut connections are in nearly every deep network, including language models.'],
    ['The vanishing gradient problem', 'Very deep networks'],
    (C) => `More layers would not have helped Marginalia. Last month it learned from ${C.shown.titlesShown} titles, because those were the ones on its screens.`, [], 'model',
    'Whisper a message down a long line of people. How would you stop it getting garbled?', 'Why does a long chain lose the message?', ['He, K., Zhang, X., Ren, S., & Sun, J. (2016). Deep Residual Learning for Image Recognition. CVPR.']),
  S('III-10', false, 'munich', ['Sepp Hochreiter', 'Long short-term memory', '1997', 'recorded at the Technical University of Munich'], ['Jürgen Schmidhuber'],
    ['A network that reads a sequence one step at a time tends to forget how it began.', 'Sepp Hochreiter analysed why in his thesis at the Technical University of Munich in 1991. With Jürgen Schmidhuber he published a fix in 1997: a memory cell guarded by gates.', 'The gates learn what to keep and what to let go.'],
    ['They wanted a network that could connect events far apart in time.', 'Whatever is not kept on purpose fades.', 'For two decades it was the standard model for speech, handwriting and translation.'],
    ['Recurrent networks', 'Memory over time', 'Gradients that vanish in time'],
    (C) => `Marginalia weighs a reader’s last ${C.planted.remembers} loans heavily and has all but forgotten the ${C.planted.forgets} before them.`, [[5, 1]], 'model',
    'Read a long sentence aloud. By the end, do you remember how it started?', 'How does it choose what to forget?', ['Hochreiter, S., & Schmidhuber, J. (1997). Long Short-Term Memory. Neural Computation, 9(8).']),
  S('III-11', false, 'apple', ['Tom Gruber, Dag Kittlaus and Adam Cheyer', 'Siri', '2011', 'Apple, begun at SRI International'], [],
    ['Siri began as a company spun out of SRI International, founded by Dag Kittlaus, Adam Cheyer and Tom Gruber.', 'Apple bought the company in 2010 and shipped the assistant on a phone in 2011.', 'To turn sound into words, a recognizer weighs two things: what the sound resembles, and which words are likely to be said.'],
    ['They wanted an assistant that did things when asked in ordinary speech.', 'When the sound is unclear, the likelier word wins, and unusual names lose.', 'Voice assistants, dictation and captions all make this trade.'],
    ['Speech recognition and assistants', 'Bayes’ rule at work'],
    (C) => `Asked aloud for a rare title, the library’s kiosk hears a bestseller that sounds a little like it. Its idea of what is likely comes from the loan counts.`, [[5, 1]], 'model',
    'Say an unusual name to a voice assistant. What does it hear?', 'Why does it hear the common word?', ['Apple (2011). Apple Launches iPhone 4S, iOS 5 & iCloud. Press release, 4 October 2011.']),
  S('III-12', false, 'montreal', ['Ian Goodfellow and colleagues', 'Generative adversarial networks', '2014', 'Université de Montréal'], [],
    ['Ian Goodfellow and colleagues at the Université de Montréal set two networks against each other in 2014.', 'One makes fakes. The other tries to tell fakes from real examples. Each improves by trying to beat the other.', 'A known weakness: the forger may settle on a few safe designs. It is called mode collapse.'],
    ['They wanted a network that could produce new, realistic examples.', 'A forger that only needs to pass inspection has no reason to be varied.', 'The idea drove a decade of image generation.'],
    ['Generative models', 'Two networks in competition'],
    (C) => `A generator that plays safe makes one thing. Marginalia’s safest five are the same for almost everyone.`, [[5, 1]], 'model',
    'If you could get full marks by always drawing the same picture, would you draw anything else?', 'Why would it only make one thing?', ['Goodfellow, I., et al. (2014). Generative Adversarial Nets. Advances in Neural Information Processing Systems 27.']),
  S('III-13', false, 'amsterdam', ['Diederik Kingma and Max Welling', 'The variational autoencoder', '2013', 'University of Amsterdam'], [],
    ['Diederik Kingma and Max Welling, in Amsterdam, wanted an autoencoder whose middle layer could be sampled to make new examples.', 'Their 2013 method encodes each input as a small cloud instead of a point, and asks the clouds to stay near the middle of the map.', 'Nearby places on the map then decode to similar things.'],
    ['They wanted a smooth map of the data that you could walk around in.', 'Where few examples land, the decoder has little to go on and the output blurs.', 'Compact, smooth codes are the first stage of many image generators.'],
    ['Latent variables', 'Encoding with noise', 'Decoding'],
    (C) => `The middle of Marginalia’s map of books is crowded and sharp. At the edges, where the odd books sit, it has seen too little to draw clearly.`, [[5, 1]], 'model',
    'Draw a map of your street from memory. Which parts are fuzzy?', 'Why are the edges blurry?', ['Kingma, D. P., & Welling, M. (2013). Auto-Encoding Variational Bayes. arXiv:1312.6114.']),
  S('III-14', false, 'berkeley', ['Jonathan Ho, Ajay Jain and Pieter Abbeel', 'Denoising diffusion', '2020', 'UC Berkeley'], [],
    ['Add a little noise to a picture, again and again, until nothing is left but static.', 'Jonathan Ho, Ajay Jain and Pieter Abbeel, at Berkeley in 2020, trained a network to undo one small step of that noise, and showed it could make sharp images by starting from static and walking back.', 'The idea of learning to reverse diffusion had been proposed in 2015 by Jascha Sohl-Dickstein and colleagues.'],
    ['They wanted image generation that was stable to train.', 'Push the result hard toward “typical” and every result looks alike.', 'Most picture generators now work by removing noise step by step.'],
    ['Diffusion models', 'Guidance'],
    (C) => `Guidance trades variety for the typical. A recommender tuned only for the likeliest loan makes the same trade.`, [[5, 1]], 'model',
    'Shake a jar of sand and pebbles. Could you un-shake it?', 'What do you lose when you ask for “the usual”?', ['Ho, J., Jain, A., & Abbeel, P. (2020). Denoising Diffusion Probabilistic Models. Advances in Neural Information Processing Systems 33.']),
  S('III-15', false, 'apple', ['Ashish Shrivastava, Tomas Pfister and Oncel Tuzel', 'Learning from simulated images', '2017', 'Apple'], ['Josh Susskind', 'Wenda Wang', 'Russ Webb'],
    ['Labelled photographs are expensive. Computer-drawn pictures come with labels for free, but they look computer-drawn.', 'In one of the first research papers Apple published on machine learning, Ashish Shrivastava and colleagues trained a refiner network to make synthetic images look real while keeping their labels.', 'A second network judged whether each refined image passed.'],
    ['They wanted cheap synthetic data that trained models as well as real data.', 'A model tested only on a simulation inherits the simulation’s assumptions.', 'Synthetic data is routine in vision, robotics and privacy work.'],
    ['Synthetic data', 'The gap between simulation and the world'],
    (C) => `The engineer tested each version of Marginalia on simulated readers. The simulated readers could only pick from the screen.`, [[4, -1]], 'evaluate',
    'Is practising on a driving game the same as driving?', 'What can a pretend reader not tell you?', ['Shrivastava, A., et al. (2017). Learning from Simulated and Unsupervised Images through Adversarial Training. CVPR.']),
  S('III-16', true, 'london', ['Volodymyr Mnih and David Silver', 'Deep Q-learning', '2015', 'Google DeepMind, London'], [],
    ['Volodymyr Mnih, David Silver and colleagues at DeepMind gave one network the screen and the score of old Atari games, and nothing else.', 'It learned by trial and reward. In 2015 they reported it playing many of the games as well as a person.', 'To learn, it had to try moves it did not yet think were best.'],
    ['They wanted one learning method that worked across many different games.', 'An agent that never tries the unknown cannot find out it was wrong.', 'Trading a little reward now for knowledge later runs through advertising, medicine and robotics.'],
    ['Reinforcement learning', 'Reward', 'Exploration and exploitation'],
    (C) => `Marginalia never explores. All five slots go to what it already believes is best. A few random slots would find good rare books, and would measure what display does.`, [[5, 1]], 'model',
    'Do you order your favourite every time, or sometimes try something new? What do you lose either way?', 'Why try something you think is worse?', ['Mnih, V., et al. (2015). Human-level control through deep reinforcement learning. Nature, 518.']),
  S('III-17', false, 'london', ['David Silver, Aja Huang and Demis Hassabis', 'AlphaGo', '2016', 'Google DeepMind, London'], [],
    ['Go has too many positions to search the way chess programs do.', 'AlphaGo, from DeepMind, joined a search that plays games out with two networks: one suggests promising moves, one judges positions.', 'In March 2016 it won four games of five against Lee Sedol, one of the strongest players in the world.'],
    ['They wanted to play a game long thought out of reach for machines.', 'A search only looks as far ahead as it is told to.', 'Search guided by learned hunches is used for chemistry, chip layout and mathematics.'],
    ['Search guided by learning', 'Self-play'],
    (C) => `Marginalia looks one move ahead, to the next loan. Nobody asked it about the reader a year from now.`, [], 'model',
    'In noughts and crosses, how many moves ahead do you think?', 'What if the best next move is bad later?', ['Silver, D., et al. (2016). Mastering the game of Go with deep neural networks and tree search. Nature, 529.']),
  S('III-18', false, 'london', ['John Jumper and colleagues', 'AlphaFold', '2021', 'Google DeepMind, London'], [],
    ['A protein is a chain that folds into a shape, and the shape decides what it does. Working out one shape in a laboratory can take years.', 'In 2021 John Jumper and colleagues at DeepMind described AlphaFold, which predicts the shape from the sequence of the chain.', 'At a blind assessment in 2020 its predictions were often close to laboratory accuracy.'],
    ['They wanted shapes for the many proteins nobody had measured.', 'It leans on related sequences. Where there are few relatives, it is less sure.', 'Predicted structures are now a starting point across biology.'],
    ['AI in science', 'Structure from sequence'],
    (C) => `Books borrowed by the same readers sit close together on a map nobody drew. For rare books there are too few readers to place them.`, [], 'model',
    'Fold a paper chain so the red links touch. How many ways are there?', 'How can it guess a shape nobody has seen?', ['Jumper, J., et al. (2021). Highly accurate protein structure prediction with AlphaFold. Nature, 596.']),
  S('III-19', true, 'princeton', ['Allison Chaney, Brandon Stewart and Barbara Engelhardt', 'Algorithmic confounding', '2018', 'Princeton University'], [],
    ['A recommender is trained on what people chose. But people choose from what the recommender showed them.', 'Allison Chaney, Brandon Stewart and Barbara Engelhardt, at Princeton in 2018, simulated that loop.', 'They found that users’ behaviour grew more alike over time, without their being better served.'],
    ['They wanted to know what happens when a system is trained on data it helped to produce.', 'The loop makes a system look more accurate while it makes its users more alike.', 'It is a standing warning for any system that learns from its own results.'],
    ['Feedback loops', 'Simultaneity seen again'],
    (C) => `The paradox can be built from four plain rules: show, borrow, log, retrain. That proves it is possible. It does not prove it happened at the Common Shelf.`, [[5, 2]], 'explain',
    'If the cook only makes what was eaten yesterday, what happens to the menu?', 'If it could happen, did it happen?', ['Chaney, A. J. B., Stewart, B. M., & Engelhardt, B. E. (2018). How Algorithmic Confounding in Recommendation Systems Increases Homogeneity and Decreases Utility. RecSys.']),
];

export const PART4 = [
  S('IV-1', true, 'belllabs', ['Claude Shannon', '“Prediction and Entropy of Printed English”', '1951', 'Bell Labs'], [],
    ['Claude Shannon asked how predictable English is.', 'He had people guess a hidden text one letter at a time and counted their guesses. Most letters were guessed at the first try.', 'From those counts he estimated that English carries roughly one bit of surprise per letter, far less than random letters would.'],
    ['He wanted to measure how much of language is redundant.', 'A text that is easy to predict carries little news.', 'A language model is a machine for making exactly these guesses.'],
    ['Language as prediction', 'Entropy', 'n-gram models'],
    (C) => `Six years ago a reader’s next loan was hard to guess: ${C.guess.bitsFirst.toFixed(1)} bits of surprise. Now it is ${C.guess.bitsLast.toFixed(1)} bits. The board calls the difference accuracy.`, [[4, -1]], 'describe',
    'Finish this: “Once upon a ___”. How did you know?', 'If you can always guess what comes next, did you learn anything?', ['Shannon, C. E. (1951). Prediction and Entropy of Printed English. Bell System Technical Journal, 30(1).']),
  S('IV-2', false, 'google', ['Tomas Mikolov, Kai Chen and Greg Corrado', 'word2vec', '2013', 'Google'], ['Jeffrey Dean'],
    ['Tomas Mikolov and colleagues at Google trained a very simple network on billions of words in 2013.', 'Its only job was to predict a word from its neighbours. As a by-product, each word got a list of numbers: a position in space.', 'Words used in similar company landed close together, and some relations became directions.'],
    ['They wanted word representations that were cheap enough to learn from very large text.', 'A word seen only a few times is placed almost at random.', 'Representing things as points in a learned space is now everywhere.'],
    ['Word vectors', 'Skip-gram and CBOW', 'GloVe'],
    (C) => `Rare titles drift at the edge of Marginalia’s map. It has seen them in too few readers’ lists to place them.`, [[5, 1]], 'engineer',
    'Which words keep company with “library”? With “storm”?', 'How can a word be a place?', ['Mikolov, T., Chen, K., Corrado, G., & Dean, J. (2013). Efficient Estimation of Word Representations in Vector Space. arXiv:1301.3781.']),
  S('IV-3', false, 'meta', ['Piotr Bojanowski, Edouard Grave and Armand Joulin', 'fastText', '2016', 'Facebook AI Research'], ['Tomas Mikolov'],
    ['A word-vector model has nothing to say about a word it never saw.', 'Piotr Bojanowski, Edouard Grave, Armand Joulin and Tomas Mikolov, at Facebook’s research lab, built each word’s vector from the vectors of its character pieces.', 'A new word made of familiar pieces gets a sensible place straight away.'],
    ['They wanted good vectors for rare words and for languages with many word forms.', 'Pieces carry spelling, not meaning. Two words can look alike and mean nothing alike.', 'Building the unfamiliar from familiar parts is how every modern language model reads.'],
    ['Subword features'],
    (C) => `A rare author’s name can be placed by its parts. The same idea would let a rare book borrow strength from books like it.`, [], 'engineer',
    'What might “unsnackable” mean? How did you work it out?', 'Can you guess a word you have never seen?', ['Bojanowski, P., Grave, E., Joulin, A., & Mikolov, T. (2017). Enriching Word Vectors with Subword Information. Transactions of the ACL, 5.']),
  S('IV-4', false, 'edinburgh', ['Rico Sennrich, Barry Haddow and Alexandra Birch', 'Byte-pair encoding for translation', '2016', 'University of Edinburgh'], [],
    ['A translation model has a fixed list of words, and real text is full of names and rare words that are not on it.', 'Rico Sennrich, Barry Haddow and Alexandra Birch, at Edinburgh, borrowed an old compression trick: start from single characters and keep merging the commonest neighbouring pair.', 'Common words end up whole. Rare ones are spelled out in pieces.'],
    ['They wanted a translator that could handle any word at all.', 'Rare names cost more pieces, so they take up more room and are easier to get wrong.', 'Almost every language model reads text as pieces made this way.'],
    ['Tokenization'],
    (C) => `In Octavo’s vocabulary a common word is one token. A rare author’s name shatters into many.`, [], 'engineer',
    'Which pairs of letters turn up most in your name? In “the”?', 'Why do long odd names break into bits?', ['Sennrich, R., Haddow, B., & Birch, A. (2016). Neural Machine Translation of Rare Words with Subword Units. ACL.']),
  S('IV-5', false, 'montreal', ['Dzmitry Bahdanau, Kyunghyun Cho and Yoshua Bengio', 'Attention', '2014', 'Université de Montréal'], [],
    ['Early neural translators squeezed a whole sentence into one fixed list of numbers before writing the translation. Long sentences did not fit.', 'Dzmitry Bahdanau, Kyunghyun Cho and Yoshua Bengio let the model look back at the source words while writing each new word.', 'It learned where to look by itself. They called it attention.'],
    ['They wanted translation that did not fall apart on long sentences.', 'Attention is shared out. What one word gets, another does not.', 'Attention became the main building block of language models.'],
    ['Sequence-to-sequence models', 'Attention'],
    (C) => `Octavo’s attention adds up to one. What goes to the bestsellers has to come from every other book.`, [], 'model',
    'When you translate a sentence, which words do you look back at?', 'Can you pay attention to everything at once?', ['Bahdanau, D., Cho, K., & Bengio, Y. (2015). Neural Machine Translation by Jointly Learning to Align and Translate. ICLR.']),
  S('IV-6', true, 'google', ['Ashish Vaswani, Jakob Uszkoreit and Llion Jones', 'The Transformer', '2017', 'Google'], ['Noam Shazeer', 'Niki Parmar', 'Aidan Gomez', 'Łukasz Kaiser', 'Illia Polosukhin'],
    ['Eight researchers at Google asked in 2017 whether a model could be built from attention alone, with no step-by-step reading.', 'In their Transformer every word looks at every other word at once, and the layers repeat.', 'Because nothing has to wait its turn, it trains quickly on large machines. Today’s language models are built on it.'],
    ['They wanted a translator that trained faster than the step-by-step kind.', 'Without a marker for position, it cannot tell “dog bites man” from “man bites dog”.', 'It is the design behind the language models people use every day.'],
    ['Self-attention', 'Positions', 'Layers'],
    (C) => `In Octavo, the titles it has seen most pull attention like magnets. Ask about a quiet subject and its attention still slides to the bestsellers.`, [[5, 1]], 'model',
    'In “the trophy did not fit in the case because it was too big”, what is “it”? How do you know?', 'How does a word know which other words matter?', ['Vaswani, A., et al. (2017). Attention Is All You Need. Advances in Neural Information Processing Systems 30.']),
  S('IV-7', false, 'google', ['Jacob Devlin, Ming-Wei Chang and Kristina Toutanova', 'BERT', '2018', 'Google'], ['Kenton Lee'],
    ['Jacob Devlin and colleagues at Google trained a Transformer in 2018 by hiding some words in a sentence and asking for them back.', 'To fill a gap the model must use the words on both sides.', 'Once trained on plain text, it could be adapted to many tasks with a small amount of labelled data.'],
    ['They wanted one pre-trained model that could be reused for many language tasks.', 'Asked to fill a gap, it writes what it has seen most.', 'Pre-train on plain text, then adapt: that is now the usual order of work.'],
    ['Masked language models', 'Pre-training then fine-tuning', 'Encoders and decoders'],
    (C) => `Asked to fill a gap in a reading list, the model writes in the title it has seen most.`, [[5, 1]], 'model',
    'Fill the blank: “The cat sat on the ___.” Now: “The ___ sat on the mat.” Which was easier?', 'Why does it always pick the usual word?', ['Devlin, J., Chang, M.-W., Lee, K., & Toutanova, K. (2019). BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding. NAACL.']),
  S('IV-8', true, 'sf', ['Alec Radford, Karthik Narasimhan and Tim Salimans', 'Generative pre-training', '2018', 'OpenAI, San Francisco'], ['Ilya Sutskever'],
    ['Alec Radford and colleagues at OpenAI trained a Transformer in 2018 on one task: given the text so far, predict the next piece.', 'Then they adapted it to other tasks with little extra training.', 'Later and much larger models of the same kind turned out to write fluent text, one token at a time.'],
    ['They wanted to learn from plain text, which is plentiful, instead of labelled text, which is scarce.', 'A model retrained on its own writing loses the rare words first.', 'This is the design of the chat assistants now in wide use.'],
    ['Next-token prediction', 'Sampling', 'A model trained on its own output'],
    (C) => `At temperature zero Octavo says the likeliest thing every time. Retrained on its own output it forgets the rare words first. Marginalia does this with books: retrained each month on loans its own screen produced.`, [[5, 1]], 'model',
    'Copy a drawing, then copy the copy, ten times. What happens to the small details?', 'Why does copying yourself make you forget things?', ['Radford, A., Narasimhan, K., Salimans, T., & Sutskever, I. (2018). Improving Language Understanding by Generative Pre-Training. OpenAI.', 'Shumailov, I., et al. (2024). AI models collapse when trained on recursively generated data. Nature, 631.']),
  S('IV-9', false, 'sf', ['Tom Brown and colleagues; Jason Wei and colleagues', 'Few-shot learning and chain of thought', '2020 and 2022', 'OpenAI and Google'], [],
    ['In 2020 Tom Brown and colleagues at OpenAI reported that a large language model could do a new task from a few examples written into its prompt, with no retraining.', 'In 2022 Jason Wei and colleagues at Google showed that examples which spell out the steps help with problems that need several steps.', 'How you ask became part of the method.'],
    ['They wanted to know how much a trained model could do with instructions alone.', 'A prompt steers the model. It does not change what the model was trained on.', 'Writing clear prompts with examples is now an everyday skill.'],
    ['Prompts', 'Zero-shot and few-shot', 'Working step by step'],
    (C) => `Octavo, the library’s chat assistant, sits on top of Marginalia’s ranking. However it is asked, its suggestions come from the same short list.`, [[5, 1]], 'model',
    'Explain how to make tea to someone who has never seen a kettle. What did you forget to say?', 'Why does it help to show your working?', ['Brown, T., et al. (2020). Language Models are Few-Shot Learners. Advances in Neural Information Processing Systems 33.', 'Wei, J., et al. (2022). Chain-of-Thought Prompting Elicits Reasoning in Large Language Models. Advances in Neural Information Processing Systems 35.']),
  S('IV-10', false, 'sf', ['Paul Christiano and Jan Leike', '“Deep Reinforcement Learning from Human Preferences”', '2017', 'recorded at OpenAI and DeepMind'], ['Tom Brown', 'Miljan Martic', 'Shane Legg', 'Dario Amodei'],
    ['Some goals are hard to write down as a score. What does a good backflip look like?', 'Paul Christiano, Jan Leike and colleagues showed people pairs of short clips and asked which was better.', 'A second model learned to predict those choices, and its predictions served as the reward. Under a thousand comparisons taught a simulated robot a backflip.'],
    ['They wanted to teach behaviour that people can recognise but cannot specify.', 'The learned reward captures what people clicked, which may not be what they meant.', 'Learning from people’s comparisons is one way chat assistants are tuned.'],
    ['Learning from feedback', 'Reward models', 'The gap between what was asked and what was meant'],
    (C) => `Marginalia learned from one signal, the loan. Nobody ever asked a reader which of two shelves they would rather have seen.`, [[5, 1]], 'model',
    'Which of two drawings is better? Can you say exactly why?', 'What if I pick the one I like for a silly reason?', ['Christiano, P., et al. (2017). Deep Reinforcement Learning from Human Preferences. Advances in Neural Information Processing Systems 30.']),
  S('IV-11', false, 'microsoft', ['Edward Hu, Yelong Shen and colleagues', 'LoRA', '2021', 'Microsoft'], [],
    ['Retraining every weight of a large model for each new job is costly, and leaves a full copy for every job.', 'Edward Hu, Yelong Shen and colleagues at Microsoft froze the model and trained only a pair of thin matrices added alongside each layer.', 'The patch is tiny compared with the model and can be swapped in and out.'],
    ['They wanted cheap, swappable adaptations of one large model.', 'Whatever the patch is trained on, it pulls the model toward.', 'Small patches are a common way to customise a language model.'],
    ['Fine-tuning', 'Low-rank updates', 'Smaller models'],
    (C) => `Fine-tuned on last year’s loans, the assistant leans toward last year’s loans. ${p(C.titles.zeroLast)} of the catalogue was not borrowed last year, so the patch has nothing to say about it.`, [[5, 1]], 'model',
    'If you only practise this week’s spellings, what happens to last month’s?', 'Does learning one thing make you forget another?', ['Hu, E. J., et al. (2022). LoRA: Low-Rank Adaptation of Large Language Models. ICLR.']),
  S('IV-12', false, 'sf', ['Alec Radford and Jong Wook Kim', 'CLIP', '2021', 'OpenAI, San Francisco'], ['their co-authors'],
    ['Alec Radford, Jong Wook Kim and colleagues at OpenAI collected four hundred million pictures with their captions.', 'They trained two networks, one for images and one for text, so that a picture and its own caption land close together and mismatched pairs land far apart.', 'The result can label a kind of picture it was never trained to label: write the candidate labels as text and see which is nearest.'],
    ['They wanted a vision model that learned from ordinary captions instead of hand-made labels.', 'It can be fooled by a written word stuck on the picture.', 'Shared spaces for pictures and text sit inside image search and image generators.'],
    ['Pictures and text in one space', 'Contrastive learning', 'Zero-shot labels'],
    (C) => `A cover that looks like a bestseller is placed beside the bestsellers, whatever is inside the book.`, [], 'engineer',
    'Match five family photos to five captions. What clues did you use?', 'Can you judge a book by its cover?', ['Radford, A., et al. (2021). Learning Transferable Visual Models From Natural Language Supervision. ICML.']),
  S('IV-13', true, 'meta', ['Patrick Lewis, Ethan Perez, Sebastian Riedel and colleagues', 'Retrieval-augmented generation', '2020', 'Facebook AI Research'], [],
    ['A language model answers from what it absorbed in training, and cannot say where a fact came from.', 'Patrick Lewis, Ethan Perez, Sebastian Riedel and colleagues, in 2020, had the model first fetch passages from a library of text and then write its answer with those passages in view.', 'The library can be updated without retraining the model.'],
    ['They wanted answers that were grounded in sources and could be updated.', 'The answer can only be as good as what was fetched.', 'Chat assistants that cite documents work this way.'],
    ['Retrieval', 'Grounding', 'Citing sources'],
    (C) => `Octavo retrieves by loan count. What it fetches is what is already borrowed most, so retrieval is display under another name.`, [[5, 1]], 'model',
    'If you may only look in three books to answer a question, who picks the three?', 'What if the right book was never fetched?', ['Lewis, P., et al. (2020). Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks. Advances in Neural Information Processing Systems 33.']),
  S('IV-14', false, 'princeton', ['Shunyu Yao and colleagues', 'ReAct', '2022', 'Princeton University'], [],
    ['Shunyu Yao and colleagues, at Princeton and Google, had a language model alternate between two kinds of step.', 'It writes a thought about what to do next. Then it takes an action, such as a search, and reads the result before thinking again.', 'Reasoning and acting in turn did better than either alone on the tasks they tried.'],
    ['They wanted a model that could look things up and use what it found.', 'A loop with no stopping rule can repeat the same step for ever.', 'Assistants that use tools run a loop like this one.'],
    ['Tools and agents', 'Think, act, observe'],
    (C) => `Asked to “find something good”, the agent calls the same tool every time: the bestseller list.`, [[5, 1]], 'model',
    'To find out when the shop shuts, what are your steps? What if the first one fails?', 'How does it know when to stop?', ['Yao, S., et al. (2023). ReAct: Synergizing Reasoning and Acting in Language Models. ICLR.']),
  S('IV-15', true, 'cornell', ['Tobias Schnabel, Adith Swaminathan and Thorsten Joachims', '“Recommendations as Treatments”', '2016', 'Cornell University'], ['Ashudeep Singh', 'Navin Chandak'],
    ['Ratings and clicks are collected only for what people were shown, and people are not shown things at random.', 'Tobias Schnabel, Adith Swaminathan, Thorsten Joachims and colleagues, at Cornell in 2016, treated each recommendation like a treatment in a medical study.', 'If you know the chance that each item was shown, you can reweight the data to undo the selection.'],
    ['They wanted to learn and to evaluate fairly from data that a recommender had shaped.', 'The correction needs to know what was shown, and with what chance.', 'Randomizing a small share of what is shown is how large services measure what display does.'],
    ['Exposure and selection', 'Position bias', 'Weighting by the chance of being shown'],
    (C) => `The blank column gets its name: shown. Where a loan came from a screen, the first slot took ${p(C.slots.adult[0])} of adult choices and the fifth ${p(C.slots.adult[4])}. In the children’s room the first slot took ${p(C.slots.child[0])}.`, [[5, 3]], 'explain',
    'In a shop, what is at eye level? Who put it there?', 'Do I pick the first one because it is best, or because it is first?', ['Schnabel, T., Swaminathan, A., Singh, A., Chandak, N., & Joachims, T. (2016). Recommendations as Treatments: Debiasing Learning and Evaluation. ICML.']),
  S('IV-16', true, 'microsoft', ['Cynthia Dwork and Frank McSherry', 'Differential privacy', '2006', 'Microsoft Research'], ['Kobbi Nissim', 'Adam Smith'],
    ['Publishing even a harmless-looking count can leak something about one person.', 'In 2006 Cynthia Dwork, Frank McSherry, Kobbi Nissim and Adam Smith gave a definition of privacy that can be proved: the published answer should barely change whether or not any one person is in the data.', 'You get it by adding carefully measured random noise.'],
    ['They wanted a promise about privacy that did not depend on what an attacker already knows.', 'More privacy means more noise. Small groups get blurrier answers.', 'Census offices and phone makers publish statistics this way.'],
    ['Privacy', 'Randomized response', 'Noise and a budget'],
    (C) => `The library kept no history of screens partly because reading is private. The column can be kept another way: as noisy counts per title and slot, with no reader attached.`, [], 'collect',
    'How could a class find out how many pupils skipped breakfast without anyone admitting it?', 'How can a wrong answer on purpose give a right answer overall?', ['Dwork, C., McSherry, F., Nissim, K., & Smith, A. (2006). Calibrating Noise to Sensitivity in Private Data Analysis. Theory of Cryptography Conference.']),
  S('IV-17', true, 'sf', ['Chris Olah, Trenton Bricken, Adly Templeton and colleagues', 'Features from sparse autoencoders', '2023 and 2024', 'Anthropic, San Francisco'], [],
    ['Inside a neural network a single unit often responds to several unrelated things.', 'Researchers at Anthropic, among them Chris Olah, Trenton Bricken and Adly Templeton, trained a second, sparse network to rewrite the activity of a layer as a longer list of features that each respond to one thing.', 'In 2023 and 2024 they reported features for many recognisable ideas, and showed that turning a feature up changes what the model writes.'],
    ['They wanted to read what a network has learned, in units a person can name.', 'The dictionary is a description of the network, and a description can miss things.', 'Looking inside models is a growing part of testing them.'],
    ['Looking inside a network', 'Superposition', 'Sparse dictionaries'],
    (C) => `Inside Marginalia 3 one feature tracks “was on a screen last month”. Its link to what gets shown next is ${C.importance.lastMonth.toFixed(2)}. For the quality of the book the figure is ${C.importance.quality.toFixed(2)}.`, [[5, 2]], 'explain',
    'If one light switch worked three different lamps, how would you find out which?', 'Can you look inside a machine’s head?', ['Bricken, T., et al. (2023). Towards Monosemanticity: Decomposing Language Models With Dictionary Learning. Anthropic.', 'Templeton, A., et al. (2024). Scaling Monosemanticity: Extracting Interpretable Features from Claude 3 Sonnet. Anthropic.']),
];
